import express from 'express';

const DIIZINKAN = ['https://web.tokosari.id'];
function corsSederhana(req, res, next) {
  const asal = req.get('origin');
  if (asal && DIIZINKAN.includes(asal)) res.set('Access-Control-Allow-Origin', asal);
  next();
}
function headerAman(req, res, next) {
  res.set('X-Content-Type-Options', 'nosniff');
  res.removeHeader('X-Powered-By');
  next();
}
function batasi(maks) {
  const hitung = new Map();
  return (req, res, next) => {
    const kunci = req.get('x-klien') ?? 'anonim';
    const n = (hitung.get(kunci) ?? 0) + 1;
    hitung.set(kunci, n);
    if (n > maks) return res.status(429).json({ error: 'Terlalu banyak permintaan' });
    next();
  };
}
const app = express();
app.use(headerAman, corsSederhana, batasi(2));
app.get('/menu', (req, res) => res.json(['Kopi']));
const server = app.listen(3000);

for (const asal of ['https://web.tokosari.id', 'https://situs-lain.com', 'https://web.tokosari.id']) {
  const r = await fetch('http://localhost:3000/menu', { headers: { Origin: asal, 'X-Klien': 'hp-rina' } });
  console.log(r.status, r.headers.get('access-control-allow-origin'), r.headers.get('x-powered-by'));
}
server.close();

